package com.pousada;

import com.pousada.db.Database;
import com.pousada.domain.Reservation;
import com.pousada.repository.MessageRepository;
import com.pousada.repository.ReservationRepository;
import com.pousada.repository.RoomRepository;
import com.pousada.service.MessageService;
import com.pousada.service.ReservationService;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.testcontainers.containers.PostgreSQLContainer;

import java.math.BigDecimal;
import java.time.LocalDate;

import static org.junit.Assert.*;

public class ReservationFlowIT {
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:18-alpine")
            .withDatabaseName("pousada")
            .withUsername("pousada")
            .withPassword("pousada");

    static {
        postgres.start();
        System.setProperty("DB_URL", postgres.getJdbcUrl());
        System.setProperty("DB_USER", postgres.getUsername());
        System.setProperty("DB_PASSWORD", postgres.getPassword());
    }

    private ReservationService reservationService;
    private ReservationRepository reservationRepo;
    private RoomRepository roomRepo;
    private MessageService messageService;

    @Before
    public void setUp() throws Exception {
        Database.initialize();
        roomRepo = new RoomRepository();
        reservationRepo = new ReservationRepository();
        messageService = new MessageService(new MessageRepository());
        reservationService = new ReservationService(reservationRepo, roomRepo, messageService);
    }

    @Test
    public void testCompleteReservationFlow() throws Exception {
        // Create reservation
        Reservation reservation = reservationService.create(
            201,
            "João Silva",
            "joao@email.com",
            "12345678901",
            LocalDate.of(2027, 3, 10),
            LocalDate.of(2027, 3, 12),
            2,
            "STANDARD",
            null
        );

        assertEquals(Reservation.Status.PENDING, reservation.getStatus());
        assertEquals(BigDecimal.ZERO, reservation.getAmountPaid());
        assertTrue(reservation.getSubtotal().compareTo(BigDecimal.ZERO) > 0);

        // Confirm reservation
        Reservation confirmed = reservationService.confirm(
            reservation.getId(),
            reservation.getTotal()
        );
        assertEquals(Reservation.Status.CONFIRMED, confirmed.getStatus());
        assertEquals(confirmed.getTotal(), confirmed.getAmountPaid());

        // Check-in
        Reservation checkedIn = reservationService.checkIn(reservation.getId());
        assertEquals(Reservation.Status.CHECKED_IN, checkedIn.getStatus());

        // Check-out
        Reservation checkedOut = reservationService.checkOut(reservation.getId());
        assertEquals(Reservation.Status.CHECKED_OUT, checkedOut.getStatus());
    }

    @Test
    public void testCancellation() throws Exception {
        Reservation reservation = reservationService.create(
            202,
            "Maria Santos",
            "maria@email.com",
            "98765432101",
            LocalDate.of(2027, 4, 5),
            LocalDate.of(2027, 4, 7),
            1,
            "NON_REFUNDABLE",
            null
        );

        reservationService.confirm(reservation.getId(), reservation.getTotal());

        Reservation cancelled = reservationService.cancel(reservation.getId());
        assertEquals(Reservation.Status.CANCELLED, cancelled.getStatus());
        assertEquals(BigDecimal.ZERO, cancelled.getRefund());
    }

    @Test
    public void testCorporatePlan() throws Exception {
        Reservation reservation = reservationService.create(
            201,
            "Pedro Costa",
            "pedro@email.com",
            "11122233344",
            LocalDate.of(2027, 3, 10),
            LocalDate.of(2027, 3, 12),
            2,
            "CORPORATE",
            "TECNOSUL"
        );

        assertEquals(Reservation.Status.PENDING, reservation.getStatus());
        assertTrue(reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0);
    }

    @Test
    public void testLongStayPlan() throws Exception {
        Reservation reservation = reservationService.create(
            101,
            "Ana Silva",
            "ana@email.com",
            "55544433322",
            LocalDate.of(2027, 3, 1),
            LocalDate.of(2027, 3, 8),
            1,
            "LONG_STAY",
            null
        );

        assertEquals(Reservation.Status.PENDING, reservation.getStatus());
        assertEquals(7, reservation.getNights());
        assertTrue(reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0);
    }

    @After
    public void tearDown() {
        Database.close();
    }
}

